def quality_check_content(content):
    if not content or len(content.strip()) < 500:
        return False
    if "placeholder" in content.lower() or "lorem ipsum" in content.lower():
        return False
    if re.search(r"(Generated by|AI Assistant|ChatGPT|Claude|Gemini|DeepSeek|LLaMA)", content, re.IGNORECASE):
        return False
    quality_score = 0
    code_blocks = len(re.findall(r"```
    headers = len(re.findall(r"^#{1,6}\s+.+$", content, re.MULTILINE))
    hungarian_words = len(re.findall(r"\b[0-9a-záéíóöőúüű]{4,}\b", content, re.IGNORECASE))
    technical_terms = len(re.findall(r"\b(function|class|method|api|interface|parameter|return|example|használat|alkalmazás|példa|függvény|metódus|osztály|komponens|szolgáltatás|modul)\b", content, re.IGNORECASE))
    tables = len(re.findall(r"^\|.+\|$", content, re.MULTILINE))
    lists = len(re.findall(r"^[\*\-\+]\s+.+$", content, re.MULTILINE))
    word_count = len(content.split())
    line_count = len(content.split("\n"))
    avg_line_length = word_count / max(line_count, 1)
    noise_indicators = len(re.findall(r"(cookie|advertisement|subscribe|newsletter|spam|click here|sign up)", content, re.IGNORECASE))
    if code_blocks >= 1:
        quality_score += 12
    if code_blocks >= 3:
        quality_score += 5
    if headers >= 3:
        quality_score += 12
    if headers >= 6:
        quality_score += 5
    if hungarian_words > 150:
        quality_score += 10
    if hungarian_words > 400:
        quality_score += 5
    if technical_terms > 10:
        quality_score += 10
    if technical_terms > 25:
        quality_score += 5
    if tables > 0:
        quality_score += 8
    if tables > 2:
        quality_score += 4
    if lists >= 3:
